  var last = r.dimensionValues[r.dimensionValues.length - 1];
  return last && (last.value === 'semana_atual' || last.value === 'date_range_0');
});
const prevRows = rows.filter(function(r) {
  var last = r.dimensionValues[r.dimensionValues.length - 1];
  return last && (last.value === 'semana_anterior' || last.value === 'date_range_1');
});

// Fallback: se nao houver separacao, usar todos
const activeRows = currentRows.length > 0 ? currentRows : rows;

var sessions = 0, users = 0, bounceSum = 0, durSum = 0, convTotal = 0;
var channelMap = {};

activeRows.forEach(function(r) {
  var channel = r.dimensionValues[0].value;
  var s = parseInt(r.metricValues[0].value || '0');
  var u = parseInt(r.metricValues[1].value || '0');
  var b = parseFloat(r.metricValues[2].value || '0');
  var d = parseFloat(r.metricValues[3].value || '0');
  var c = parseFloat((r.metricValues[4] && r.metricValues[4].value) || '0');
  sessions += s; users += u; bounceSum += b; durSum += d; convTotal += c;
  channelMap[channel] = s + ' sess.';
});

var sessionsPrev = 0;
prevRows.forEach(function(r) { sessionsPrev += parseInt(r.metricValues[0].value || '0'); });

function delta(curr, prev) {
  if (prev === 0) return curr > 0 ? '+100% ↑' : '—';
  var pct = Math.round((curr - prev) / prev * 100);
  return pct >= 0 ? '+' + pct + '% ↑' : pct + '% ↓';
}

var avgBounce = activeRows.length > 0 ? (bounceSum / activeRows.length * 100).toFixed(1) + '%' : '0%';
var avgDur = activeRows.length > 0 ? Math.round(durSum / activeRows.length) : 0;
var durFmt = Math.floor(avgDur/60) + 'm' + (avgDur%60) + 's';
var channelLines = Object.entries(channelMap).map(function(e) { return '• ' + e[0] + ': ' + e[1]; }).join('\n');

// Conversoes por evento
const eventRows = eventData.rows || [];
var convWhatsApp = 0, convForm = 0;
eventRows.forEach(function(r) {
  var ev = (r.dimensionValues[0] && r.dimensionValues[0].value || '').toLowerCase();
  var cnt = parseInt((r.metricValues[0] && r.metricValues[0].value) || '0');
  if (ev === 'click') convWhatsApp = cnt;
  else if (ev === 'submit') convForm = cnt;
});

return [{
  json: {
    ga4_totalSessions: sessions,
    ga4_totalUsers: users,
    ga4_bounceRate: avgBounce,
    ga4_avgDuration: durFmt,
    ga4_delta_sessions: delta(sessions, sessionsPrev),
    ga4_sessions_ant: sessionsPrev,
    ga4_porCanal: channelLines,
    ga4_conv_whatsapp: convWhatsApp,
    ga4_conv_form: convForm,
    ga4_conv_total: Math.round(convTotal)
  }
}];

const campData = $('Ads - Campanhas').first().json;
const kwData   = $('Ads - Keywords').first().json;
const stData   = $input.first().json;

const campResults = campData.results || [];
const kwResults   = kwData.results   || [];
const stResults   = stData.results   || [];

let totalImpressions = 0, totalClicks = 0, totalCostMicros = 0, totalConversions = 0;
campResults.forEach(r => {
  totalImpressions  += parseInt(r.metrics?.impressions  || 0);
  totalClicks       += parseInt(r.metrics?.clicks       || 0);
  totalCostMicros   += parseInt(r.metrics?.costMicros   || 0);
  totalConversions  += parseFloat(r.metrics?.conversions || 0);
});

const ctr    = totalImpressions > 0 ? (totalClicks / totalImpressions * 100).toFixed(2) : '0.00';
const costBRL = (totalCostMicros / 1e6).toFixed(2);
const avgCPC  = totalClicks > 0 ? 'R$' + (totalCostMicros / 1e6 / totalClicks).toFixed(2) : 'R$0.00';

const now = new Date();
const start = new Date(); start.setDate(now.getDate() - 30);
const fmt = d => d.toISOString().slice(0, 10);

const topKw = kwResults.slice(0, 5).map(r =>
  (r.adGroupCriterion?.keyword?.text || '?') + ' (R$' + ((parseInt(r.metrics?.costMicros || 0)) / 1e6).toFixed(2) + ')'
).join(', ');

const topSt = stResults.slice(0, 5).map(r =>
  (r.searchTermView?.searchTerm || '?') + ' (' + (r.metrics?.impressions || 0) + ' impr.)'
).join(', ');

return [{
  json: {
    ads_impressions:     totalImpressions,
    ads_clicks:          totalClicks,
    ads_ctr:             ctr,
    ads_custo:           costBRL,
    ads_cpc:             avgCPC,
    ads_conversoes:      totalConversions.toFixed(1),
    ads_periodo:         fmt(start) + ' a ' + fmt(now),
    ads_top_keywords:    topKw,
    ads_top_searchterms: topSt,
  }
}];

const cur = $('Combinar Dados').first().json;
let baseline = {};
try { baseline = JSON.parse($('Ler Baseline (Redis)').first().json.baseline || '{}'); } catch(e) {}
const hasBase = baseline && baseline.gsc;

const num = v => { const n = parseFloat(String(v).replace(/[^0-9.\-]/g,'')); return isNaN(n)?0:n; };
const arrow = (now, before) => {
  const d = now - before;
  if (!hasBase) return '(sem baseline)';
  const s = d > 0 ? '↑' : (d < 0 ? '↓' : '→');
  return s + ' ' + (d>0?'+':'') + (Math.round(d*100)/100);
};

const curBase = {
  week_start: $now.toFormat('yyyy-MM-dd'),
  ts: $now.toISO(),
  gsc: { clicks: cur.gsc_totalClicks ?? 0, impressions: cur.gsc_totalImpressions ?? 0, ctr: cur.gsc_ctr ?? '0%', avgPosition: cur.gsc_avgPosition ?? '0' },
  ga4: { sessions: cur.ga4_totalSessions ?? 0, users: cur.ga4_totalUsers ?? 0, conv_form: cur.ga4_conv_form ?? 0, conv_whatsapp: cur.ga4_conv_whatsapp ?? 0, conv_total: cur.ga4_conv_total ?? 0, bounceRate: cur.ga4_bounceRate ?? '0%' },
  ads: { impressions: cur.ads_impressions ?? 0, clicks: cur.ads_clicks ?? 0, ctr: cur.ads_ctr ?? '0', custo: cur.ads_custo ?? '0.00', cpc: cur.ads_cpc ?? '0', conversoes: cur.ads_conversoes ?? '0.0' }
};

const b = hasBase ? baseline : curBase;
const periodo = (b.week_start || '?') + ' → ' + curBase.week_start;

const texto = [
  'COMPARATIVO SEMANAL Cobersystem (' + periodo + ')',
  hasBase ? '' : '[ATENÇÃO: não havia baseline de segunda; primeira leitura.]',
  '',
  'GSC cliques: ' + curBase.gsc.clicks + ' (baseline ' + b.gsc.clicks + ') ' + arrow(num(curBase.gsc.clicks), num(b.gsc.clicks)),
  'GSC impressões: ' + curBase.gsc.impressions + ' (baseline ' + b.gsc.impressions + ') ' + arrow(num(curBase.gsc.impressions), num(b.gsc.impressions)),
  'GSC posição média: ' + curBase.gsc.avgPosition + ' (baseline ' + b.gsc.avgPosition + ') ' + arrow(num(curBase.gsc.avgPosition), num(b.gsc.avgPosition)) + ' (menor é melhor)',
  'GA4 sessões: ' + curBase.ga4.sessions + ' (baseline ' + b.ga4.sessions + ') ' + arrow(num(curBase.ga4.sessions), num(b.ga4.sessions)),
  'GA4 conversões total: ' + curBase.ga4.conv_total + ' (baseline ' + b.ga4.conv_total + ') ' + arrow(num(curBase.ga4.conv_total), num(b.ga4.conv_total)),
  'GA4 conv form/wpp: ' + curBase.ga4.conv_form + '/' + curBase.ga4.conv_whatsapp + ' (baseline ' + b.ga4.conv_form + '/' + b.ga4.conv_whatsapp + ')',
  'Ads custo 30d: R$' + curBase.ads.custo + ' (baseline R$' + b.ads.custo + ') ' + arrow(num(curBase.ads.custo), num(b.ads.custo)),
  'Ads CTR: ' + curBase.ads.ctr + '% (baseline ' + b.ads.ctr + '%) ' + arrow(num(curBase.ads.ctr), num(b.ads.ctr)),
  'Ads CPC: R$' + curBase.ads.cpc + ' (baseline R$' + b.ads.cpc + ') ' + arrow(num(curBase.ads.cpc), num(b.ads.cpc)) + ' (menor é melhor)',
  'Ads conversões: ' + curBase.ads.conversoes + ' (baseline ' + b.ads.conversoes + ')'
].filter(Boolean).join('\n');

return [{ json: { dados_comparativo: texto, newBaselineJson: JSON.stringify(curBase), periodo } }];

